from dc3pa.experiments.formal_bootstrap_authorization import FormalBootstrapReadinessEvidence,audit_formal_bootstrap_authorization

def test_complete_new_condition_authorizes_formal_acquisition():
    r=FormalBootstrapReadinessEvidence(readiness_campaign_id="r",source_commit="c",blueprint_id="b",bootstrap_policy_id="p",bootstrap_amendment_id="m",run_receipt_ids=tuple(str(i) for i in range(6)),expected_run_count=6,pipeline_pass_count=6,task_completed_count=4,intervention_trigger_count=6,total_injected_logs=11,returned_model_identities=("returned-id",),returned_identity_stable_within_epoch=True,requested_returned_equality_required=False,model_epoch_id="e",task_seed_match_count=6,provider_call_contract_passed=True,no_formal_memory_writes=True,no_acquisition_writes=True,eligible=True,errors=()).with_id()
    result=audit_formal_bootstrap_authorization(source_commit="c",policy={"policy_id":"p","enabled_for_all_formal_scopes":True},amendment={"amendment_id":"m","formal_log_bootstrap_policy_id":"p","source_commit":"db8778ddcaf4655ee86cf50c9d0a9919a832d7d3","old_preacquisition_gate_superseded":True},blueprint_validation={"eligible":True,"blueprint_id":"b","report_id":"bv"},approval_binding={"blueprint_id":"b","source_commit":"c","zyf_approval_sha256":"02aa04d0bdf45d5e7dad1afb3f6ff295a687a91707c693e9d5dd9e1f040fffab","formal_log_bootstrap_policy_id":"p","formal_bootstrap_amendment_id":"m","binding_id":"ab","development_records_bootstrap_metadata":True,"final_results_report_natural_and_assisted_separately":True},taskset_release={"eligible":True,"release_id":"ts"},migration_report={"eligible":True,"report_id":"mr"},readiness=r,acquisition_schedule={"schedule_id":"s","episode_count":100,"source_commit":"c","bootstrap_policy_id":"p","bootstrap_amendment_id":"m","blueprint_id":"b","all_methods_share_policy":True,"memory_records_bootstrap_metadata":True})
    assert result.formal_acquisition_permitted
